using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "UncannyCandleOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/UncannyCandle Omen Data")]
public class UncannyCandleOmenData : OnNewRuneOmenData
{
	[Header("Uncanny Candle")]
	[SerializeField]
	private IntEvent OnModifyMaxHearts;

	[SerializeField]
	private int heartsAmount;

	[SerializeField]
	private ModifyHeartWithEffectOmenData modifyHeartWithEffectOmenData;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		OnModifyMaxHearts.Raise(heartsAmount);
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		OnModifyMaxHearts.Raise(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingHearts);
	}

	public override string OmenConvertedDescription()
	{
		return base.OmenConvertedDescription() + "\n" + modifyHeartWithEffectOmenData.GetModifyHeartsChantLocalizedDescription();
	}
}
